const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const clickOpt=async(o)=>{o.dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));o.click();await sleep(800);};
window.__state=()=>{const vals=[...document.querySelectorAll('input')].map(i=>i.value).filter(v=>v&&v!=='on');const pills=[...document.querySelectorAll('[class*=Pill-label]')].map(p=>p.textContent);return {url:location.pathname,vals,pills};};
// scope: options are in DOM; find by label text
const opts=()=>[...document.querySelectorAll('[role=option]')];
const want={FBS:true,FCS:true,'Power Four':false};
for(const [name,on] of Object.entries(want)){
  const pills=window.__state().pills; const has=pills.includes(name);
  if(has!==on){const o=opts().find(x=>x.textContent.trim()===name); if(o) await clickOpt(o);}
}
await sleep(1500);
window.__state()

